import{_ as a,o as d,c as e,O as r}from"./chunks/framework.57749cb7.js";const b=JSON.parse('{"title":"计算机基础","description":"计算机基础栏目总览：计算机网络、操作系统、gRPC 与后端安全。它们是前端与后端的共同地基，这篇讲清四篇之间的关系和阅读顺序。","frontmatter":{"description":"计算机基础栏目总览：计算机网络、操作系统、gRPC 与后端安全。它们是前端与后端的共同地基，这篇讲清四篇之间的关系和阅读顺序。"},"headers":[],"relativePath":"cs/index.md","filePath":"cs/index.md","lastUpdated":1793253837000}'),o={name:"cs/index.md"};function n(h,t,i,l,c,s){return d(),e("div",null,t[0]||(t[0]=[r('<h1 id="计算机基础" tabindex="-1">计算机基础 <a class="header-anchor" href="#计算机基础" aria-label="Permalink to &quot;计算机基础&quot;">​</a></h1><blockquote><p>前端和后端的知识树，都长在同一个根上 —— 网络、操作系统、RPC、安全。 这个栏目就是那根。四篇，按「地基程度」排序。</p></blockquote><h2 id="四篇导读" tabindex="-1">四篇导读 <a class="header-anchor" href="#四篇导读" aria-label="Permalink to &quot;四篇导读&quot;">​</a></h2><table><thead><tr><th>篇</th><th>讲什么</th><th>对应到你的其他笔记</th></tr></thead><tbody><tr><td><a href="./计算机网络原理">计算机网络原理</a></td><td>TCP/UDP、HTTP 演进、HTTPS、DNS，从物理链路到应用层</td><td>读完再去 <a href="/cao_note/backend/Java/07-Java网络编程与NIO">Java NIO</a>、<a href="/cao_note/backend/Java/Netty">Netty</a>，会明白它们为什么这么设计</td></tr><tr><td><a href="./操作系统基础">操作系统基础</a></td><td>进程线程、调度、内存管理、文件系统、IO 模型</td><td>补上 <a href="/cao_note/backend/Java/JVM深入">JVM</a>、<a href="/cao_note/backend/Java/06-JUC并发编程">JUC</a> 之下那层更底层的知识</td></tr><tr><td><a href="./gRPC与Protobuf">gRPC 与 Protobuf</a></td><td>现代跨语言 RPC：协议、编码、四种调用、生态</td><td>与 <a href="/cao_note/backend/Java/SpringCloud微服务">Zookeeper 与 RPC</a> 的 Dubbo 对照看，理解 RPC 的两代形态</td></tr><tr><td><a href="./后端安全">后端安全</a></td><td>认证授权、密码存储、加密、常见攻击防御</td><td>前端侧已有 <a href="/cao_note/frontend/前端安全/">前端安全</a>，后端这篇补齐另一半</td></tr><tr><td><a href="./重构与CodeReview">重构与 Code Review</a></td><td>坏味道清单、重构手法、以测试为安全网、Review 的维度与沟通</td><td>写完代码之后的那一半工程能力</td></tr></tbody></table><h2 id="怎么读" tabindex="-1">怎么读 <a class="header-anchor" href="#怎么读" aria-label="Permalink to &quot;怎么读&quot;">​</a></h2><ol><li><strong>先网络，再操作系统</strong>：网络是「跨机器的通信」，操作系统是「单机内部的运转」，顺序不绝对，但网络更直觉。</li><li><strong>gRPC 可以最后读</strong>：它是网络 + 序列化 + RPC 框架的综合应用，读完前两篇再看，会「哦原来如此」。</li><li><strong>安全随时穿插</strong>：它不依赖前几篇，任何阶段都能读。</li></ol><h2 id="和面试题库的关系" tabindex="-1">和面试题库的关系 <a class="header-anchor" href="#和面试题库的关系" aria-label="Permalink to &quot;和面试题库的关系&quot;">​</a></h2><p>这四篇是<strong>教程</strong>；对应的面试题在题库里另有完整的答题口径。学完一篇，去题库把对应章节刷一遍，就能把「懂原理」变成「答得上」。</p><h2 id="术语速查" tabindex="-1">术语速查 <a class="header-anchor" href="#术语速查" aria-label="Permalink to &quot;术语速查&quot;">​</a></h2><table><thead><tr><th>词</th><th>一句话</th></tr></thead><tbody><tr><td>TCP</td><td>面向连接、可靠的字节流协议</td></tr><tr><td>UDP</td><td>无连接、尽力而为的数据报协议</td></tr><tr><td>HTTP/2</td><td>基于二进制分帧，多路复用，头部压缩</td></tr><tr><td>TLS</td><td>在 TCP 之上的加密层，HTTPS = HTTP + TLS</td></tr><tr><td>进程 / 线程</td><td>资源分配单位 / CPU 调度单位</td></tr><tr><td>虚拟内存</td><td>每个进程看到连续地址空间，靠页表映射到物理内存</td></tr><tr><td>Protobuf</td><td>结构化的二进制序列化协议</td></tr><tr><td>gRPC</td><td>基于 HTTP/2 的跨语言 RPC 框架</td></tr><tr><td>OAuth2</td><td>授权框架，第三方不用拿到密码</td></tr><tr><td>SSRF</td><td>服务端被诱导去请求内网地址</td></tr></tbody></table>',10)]))}const f=a(o,[["render",n]]);export{b as __pageData,f as default};
